UPDATE ivs_part_catalog
SET data = jsonb_set(
  data,
  '{spec,shapes,1,fileDataUrl}',
  to_jsonb('data:application/octet-stream;base64,'::text)
)
WHERE id = '1bfa609d-b5b7-459a-8598-8fc07feafc3a'
  AND jsonb_array_length(data->'spec'->'shapes') = 3
  AND data->'spec'->'shapes'->1->>'fileName' = '작은바퀴_바깥면.stl'
RETURNING jsonb_array_length(data->'spec'->'shapes') AS n;
